"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def multiplyMatrices(A, B, n, m, p):
    # A is n*m, B is m*p
    result = [[0 for _ in range(p)] for _ in range(n)]
    for i in range(0, n):
        for j in range(0, p):
            for k in range(0, m):
                result[i][j] = (result[i][j] + (A[i][k] * B[k][j]))
    return result
